style.css:
@-moz-document domain("roblox.com") {
body, html {
    background: url("https://i.pinimg.com/originals/a9/6f/f0/a96ff08de6894421a74913f2b2a17d9a.gif") no-repeat center center fixed !important;
    background-size: cover !important;
    color: #ffffff !important;
  }

  /* Hacemos que el fondo de otras secciones sea transparente */
  .content, .container, .section, .rbx-header, .game-card-container {
    background-color: rgba(0, 0, 0, 0.6) !important;
  }

  .text-label, .text-overflow, .game-card-name, .section-header {
    color: #ffffff !important;
  }

  button, input, textarea {
    background-color: rgba(0, 0, 0, 0.5) !important;
    color: #ffffff !important;
    border: 1px solid #ffffff !important;
  }

  .abp, .ad-container {
    display: none !important;
  }
}
